VALUES (20260901, 'committed-on-node1')
ON CONFLICT (id) DO UPDATE
SET payload = EXCLUDED.payload, committed_at = clock_timestamp();
COMMIT;
SELECT pg_is_in_recovery() AS in_recovery,
       current_setting('transaction_read_only') AS transaction_read_only,
       pg_current_wal_lsn() AS primary_lsn,
       id, payload, committed_at
FROM replication_probe
WHERE id = 20260901;
